fn flip_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            if c.is_ascii_alphabetic() {
                // Flip case: if it's lowercase, convert to uppercase, and vice versa
                if c.is_lowercase() {
                    c.to_uppercase().next().unwrap() // Safe to unwrap since it's guaranteed to have one
                } else {
                    c.to_lowercase().next().unwrap() // Safe to unwrap since it's guaranteed to have one
                }
            } else {
                c // Keep non-alphabetic characters unchanged
            }
        })
        .collect() // Collect the results into a new Vec<char>
}